CREATE TABLE truck_configurations (id INTEGER PRIMARY KEY, event_ref INTEGER NOT NULL UNIQUE REFERENCES events (id),
    brand_id TEXT, brand_id_state TEXT NOT NULL CHECK (brand_id_state IN ('available', 'not-observed', 'not-supported', 'invalid')) CHECK ((brand_id_state = 'available') = (brand_id IS NOT NULL)), brand TEXT, brand_state TEXT NOT NULL CHECK (brand_state IN ('available', 'not-observed', 'not-supported', 'invalid')) CHECK ((brand_state = 'available') = (brand IS NOT NULL)), model_id TEXT, model_id_state TEXT NOT NULL CHECK (model_id_state IN ('available', 'not-observed', 'not-supported', 'invalid')) CHECK ((model_id_state = 'available') = (model_id IS NOT NULL)), model_name TEXT, model_name_state TEXT NOT NULL CHECK (model_name_state IN ('available', 'not-observed', 'not-supported', 'invalid')) CHECK ((model_name_state = 'available') = (model_name IS NOT NULL)), fuel_capacity_l REAL, fuel_capacity_l_state TEXT NOT NULL CHECK (fuel_capacity_l_state IN ('available', 'not-observed', 'not-supported', 'invalid')) CHECK ((fuel_capacity_l_state = 'available') = (fuel_capacity_l IS NOT NULL)),
    license_plate TEXT, license_plate_state TEXT NOT NULL CHECK (license_plate_state IN ('available', 'not-observed', 'not-supported', 'invalid')) CHECK ((license_plate_state = 'available') = (license_plate IS NOT NULL)), plate_country_id TEXT, plate_country_id_state TEXT NOT NULL CHECK (plate_country_id_state IN ('available', 'not-observed', 'not-supported', 'invalid')) CHECK ((plate_country_id_state = 'available') = (plate_country_id IS NOT NULL)), plate_country TEXT, plate_country_state TEXT NOT NULL CHECK (plate_country_state IN ('available', 'not-observed', 'not-supported', 'invalid')) CHECK ((plate_country_state = 'available') = (plate_country IS NOT NULL))) STRICT;
CREATE TABLE upload_attempt(attempt_id TEXT PRIMARY KEY,event_ref TEXT NOT NULL REFERENCES upload_envelopes(event_id),registration_ref TEXT NOT NULL REFERENCES upload_registrations(registration_id),
    credential_generation TEXT NOT NULL,connection_version INTEGER NOT NULL,started_at INTEGER NOT NULL CHECK(started_at>=0),active INTEGER NOT NULL CHECK(active IN (0,1)),outcome TEXT) STRICT;
CREATE TABLE upload_candidates(ordinal INTEGER PRIMARY KEY CHECK(ordinal>0),trip_ref INTEGER NOT NULL UNIQUE REFERENCES trips(id),trip_uuid TEXT NOT NULL UNIQUE REFERENCES trips(trip_uuid),
    opening_registration TEXT REFERENCES upload_registrations(registration_id),opening_run TEXT REFERENCES upload_scan_runs(run_id)) STRICT;
CREATE TABLE upload_change_heads(root_ref INTEGER PRIMARY KEY REFERENCES logical_trips(id),revision_ref INTEGER NOT NULL REFERENCES logical_revisions(id),
    position INTEGER NOT NULL,material_version INTEGER NOT NULL CHECK(material_version>0),material_key TEXT NOT NULL,dirty INTEGER NOT NULL CHECK(dirty IN (0,1)),mode TEXT NOT NULL DEFAULT 'live' CHECK(mode IN ('live','backfill')),run_ref TEXT REFERENCES upload_scan_runs(run_id)) STRICT;
CREATE TABLE upload_connection(id INTEGER PRIMARY KEY CHECK(id=1),client_uuid TEXT,
    legacy_boundary INTEGER NOT NULL CHECK(legacy_boundary>=0),next_ordinal INTEGER NOT NULL CHECK(next_ordinal>0),next_change INTEGER NOT NULL CHECK(next_change>0),
    version INTEGER NOT NULL DEFAULT 0 CHECK(version>=0),claimed_through INTEGER NOT NULL DEFAULT 0 CHECK(claimed_through>=0),active_registration TEXT REFERENCES upload_registrations(registration_id),credential_generation TEXT,
    active_run TEXT REFERENCES upload_scan_runs(run_id),CHECK((active_registration IS NULL)=(credential_generation IS NULL)),CHECK((active_registration IS NULL)=(active_run IS NULL))) STRICT;
INSERT INTO "upload_connection" VALUES(1,NULL,0,1,1,0,0,NULL,NULL,NULL);
CREATE TABLE upload_envelopes(event_id TEXT PRIMARY KEY,work_ref TEXT NOT NULL UNIQUE REFERENCES upload_materializations(work_id),root_ref INTEGER NOT NULL REFERENCES upload_source_bindings(root_ref),
    registration_ref TEXT NOT NULL REFERENCES upload_registrations(registration_id),mode TEXT NOT NULL CHECK(mode IN ('live','backfill')),revision INTEGER NOT NULL CHECK(revision BETWEEN 1 AND 9007199254740991),
    payload BLOB,byte_count INTEGER NOT NULL CHECK(byte_count BETWEEN 1 AND 65536),payload_digest TEXT NOT NULL,
    state TEXT NOT NULL CHECK(state IN ('queued','sending','held','delivered')),retry_at INTEGER NOT NULL DEFAULT 0 CHECK(retry_at>=0),hold_reason TEXT,
    UNIQUE(root_ref,revision)) STRICT;
CREATE TABLE upload_history_claims(first_ordinal INTEGER PRIMARY KEY CHECK(first_ordinal>=0),last_ordinal INTEGER NOT NULL CHECK(last_ordinal>=first_ordinal),
    registration_ref TEXT NOT NULL REFERENCES upload_registrations(registration_id),run_ref TEXT NOT NULL REFERENCES upload_scan_runs(run_id)) STRICT;
CREATE TABLE upload_installation(id INTEGER PRIMARY KEY CHECK(id=1),client_uuid TEXT NOT NULL UNIQUE) STRICT;
CREATE TABLE upload_materializations(work_id TEXT PRIMARY KEY,root_ref INTEGER NOT NULL REFERENCES logical_trips(id),registration_ref TEXT NOT NULL REFERENCES upload_registrations(registration_id),
    material_version INTEGER NOT NULL CHECK(material_version>0),mode TEXT NOT NULL DEFAULT 'live' CHECK(mode IN ('live','backfill')),run_ref TEXT NOT NULL REFERENCES upload_scan_runs(run_id),pin_id TEXT NOT NULL UNIQUE,state TEXT NOT NULL CHECK(state IN ('preparing','folding','complete','frozen','equal','held','stale')),
    fold_json TEXT CHECK(fold_json IS NULL OR json_valid(fold_json)),pin_json TEXT CHECK(pin_json IS NULL OR json_valid(pin_json)),
    event_ref TEXT REFERENCES upload_envelopes(event_id),pin_released INTEGER NOT NULL DEFAULT 0 CHECK(pin_released IN (0,1)),hold_reason TEXT,examined INTEGER NOT NULL DEFAULT 0 CHECK(examined BETWEEN 0 AND 100),
    UNIQUE(root_ref,material_version)) STRICT;
CREATE TABLE upload_owner_counters(registration_ref TEXT PRIMARY KEY REFERENCES upload_registrations(registration_id),change_after INTEGER NOT NULL DEFAULT 0 CHECK(change_after>=0),identity_pending_sources INTEGER NOT NULL DEFAULT 0 CHECK(identity_pending_sources>=0),identity_held_sources INTEGER NOT NULL DEFAULT 0 CHECK(identity_held_sources>=0),pending_sources INTEGER NOT NULL DEFAULT 0 CHECK(pending_sources>=0),
    held_sources INTEGER NOT NULL DEFAULT 0 CHECK(held_sources>=0),queued_events INTEGER NOT NULL DEFAULT 0 CHECK(queued_events>=0),queued_bytes INTEGER NOT NULL DEFAULT 0 CHECK(queued_bytes>=0),delivered_events INTEGER NOT NULL DEFAULT 0 CHECK(delivered_events>=0)) STRICT;
CREATE TABLE upload_projection_configurations(pin_ref TEXT NOT NULL REFERENCES upload_projection_pins(pin_id), event_ref INTEGER NOT NULL REFERENCES events(id),
    qualified INTEGER NOT NULL CHECK(qualified IN (0,1)), raw_trip_uuid TEXT NOT NULL,
    row_json TEXT NOT NULL CHECK(json_valid(row_json)), PRIMARY KEY(pin_ref,event_ref)) STRICT;
CREATE TABLE upload_projection_evidence_versions(root_ref INTEGER PRIMARY KEY REFERENCES logical_trips(id) ON DELETE CASCADE,
    generation INTEGER NOT NULL CHECK(generation>=0)) STRICT;
INSERT INTO "upload_projection_evidence_versions" VALUES(1,2);
INSERT INTO "upload_projection_evidence_versions" VALUES(2,3);
INSERT INTO "upload_projection_evidence_versions" VALUES(3,2);
INSERT INTO "upload_projection_evidence_versions" VALUES(4,2);
INSERT INTO "upload_projection_evidence_versions" VALUES(5,1);
CREATE TABLE upload_projection_intervals(pin_ref TEXT NOT NULL REFERENCES upload_projection_pins(pin_id), interval_ref INTEGER NOT NULL REFERENCES completeness_intervals(id),
    row_json TEXT NOT NULL CHECK(json_valid(row_json)), PRIMARY KEY(pin_ref,interval_ref)) STRICT;
CREATE TABLE upload_projection_members(pin_ref TEXT NOT NULL REFERENCES upload_projection_pins(pin_id), trip_ref INTEGER NOT NULL REFERENCES trips(id),
    row_json TEXT NOT NULL CHECK(json_valid(row_json)), PRIMARY KEY(pin_ref,trip_ref)) STRICT;
CREATE TABLE upload_projection_pins(
    pin_id TEXT PRIMARY KEY, incarnation_uuid TEXT NOT NULL CHECK(length(incarnation_uuid)=36), requested_trip_uuid TEXT NOT NULL REFERENCES trips(trip_uuid),
    root_ref INTEGER NOT NULL REFERENCES logical_trips(id), revision_ref INTEGER NOT NULL REFERENCES logical_revisions(id),
    evidence_generation INTEGER NOT NULL CHECK(evidence_generation>=0),
    state TEXT NOT NULL CHECK(state IN ('preparing','ready','invalidated','releasing')),
    phase TEXT NOT NULL CHECK(phase IN ('current','previous','configurations','intervals','finalize')),
    snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)), metadata_json TEXT CHECK(metadata_json IS NULL OR json_valid(metadata_json)),
    member_after INTEGER NOT NULL DEFAULT 0 CHECK(member_after>=0), item_after INTEGER NOT NULL DEFAULT 0 CHECK(item_after>=0),
    source_after INTEGER NOT NULL DEFAULT 0 CHECK(source_after>=0),
    member_count INTEGER NOT NULL DEFAULT 0 CHECK(member_count>=0), configuration_count INTEGER NOT NULL DEFAULT 0 CHECK(configuration_count>=0),
    interval_count INTEGER NOT NULL DEFAULT 0 CHECK(interval_count>=0),
    outcome_trip_ref INTEGER REFERENCES trips(id), close_trip_ref INTEGER REFERENCES trips(id),
    examined INTEGER NOT NULL DEFAULT 0 CHECK(examined BETWEEN 0 AND 100),
    CHECK((state='ready')=(metadata_json IS NOT NULL))) STRICT;
CREATE TABLE upload_queue_usage(id INTEGER PRIMARY KEY CHECK(id=1),events INTEGER NOT NULL CHECK(events BETWEEN 0 AND 10000),bytes INTEGER NOT NULL CHECK(bytes BETWEEN 0 AND 67108864),blocked INTEGER NOT NULL DEFAULT 0 CHECK(blocked IN (0,1))) STRICT;
INSERT INTO "upload_queue_usage" VALUES(1,0,0,0);
CREATE TABLE upload_receipts(event_ref TEXT PRIMARY KEY REFERENCES upload_envelopes(event_id),receipt_id TEXT NOT NULL UNIQUE,first_received INTEGER NOT NULL CHECK(first_received BETWEEN 0 AND 9007199254740991)) STRICT;
CREATE TABLE upload_registrations(registration_id TEXT PRIMARY KEY,client_uuid TEXT NOT NULL,
    origin TEXT NOT NULL,account_id TEXT NOT NULL,company_id TEXT NOT NULL,identity_epoch TEXT NOT NULL,installation_id TEXT NOT NULL,binding_id TEXT NOT NULL,
    pause_reason TEXT CHECK(pause_reason IN ('authentication','configuration','reconciliation')),UNIQUE(origin,account_id,company_id,identity_epoch)) STRICT;
CREATE TABLE upload_reservations(candidate_ref INTEGER PRIMARY KEY REFERENCES upload_candidates(ordinal),registration_ref TEXT REFERENCES upload_registrations(registration_id),
    run_ref TEXT REFERENCES upload_scan_runs(run_id),mode TEXT NOT NULL CHECK(mode IN ('live','backfill','unbound')),hold_reason TEXT,identity_state TEXT NOT NULL DEFAULT 'unbound' CHECK(identity_state IN ('unbound','pending','held','resolved','redirected')),
    CHECK((registration_ref IS NULL)=(mode='unbound')),CHECK((registration_ref IS NULL)=(run_ref IS NULL))) STRICT;
CREATE TABLE upload_scan_runs(run_id TEXT PRIMARY KEY,registration_ref TEXT NOT NULL REFERENCES upload_registrations(registration_id),request_json TEXT NOT NULL CHECK(json_valid(request_json)),
    ordinal_through INTEGER NOT NULL,change_through INTEGER NOT NULL,legacy_after INTEGER NOT NULL DEFAULT 0,ordinal_after INTEGER NOT NULL DEFAULT 0,
    phase TEXT NOT NULL DEFAULT 'legacy' CHECK(phase IN ('legacy','candidates','complete')),examined INTEGER NOT NULL DEFAULT 0 CHECK(examined BETWEEN 0 AND 100)) STRICT;
CREATE TABLE upload_source_bindings(root_ref INTEGER PRIMARY KEY REFERENCES logical_trips(id),registration_ref TEXT NOT NULL REFERENCES upload_registrations(registration_id),
    run_ref TEXT NOT NULL REFERENCES upload_scan_runs(run_id),mode TEXT NOT NULL CHECK(mode IN ('live','backfill')),game TEXT NOT NULL,plugin_session_uuid TEXT NOT NULL,trip_uuid TEXT NOT NULL UNIQUE,
    http_revision INTEGER NOT NULL DEFAULT 0 CHECK(http_revision BETWEEN 0 AND 9007199254740991),material_digest TEXT,
    terminal INTEGER NOT NULL DEFAULT 0 CHECK(terminal IN (0,1)),compared_version INTEGER NOT NULL DEFAULT 0,
    pending INTEGER NOT NULL DEFAULT 1 CHECK(pending IN (0,1)),held INTEGER NOT NULL DEFAULT 0 CHECK(held IN (0,1)),hold_reason TEXT,
    UNIQUE(game,plugin_session_uuid,trip_uuid)) STRICT;
CREATE TABLE upload_source_transitions(position INTEGER PRIMARY KEY,root_ref INTEGER NOT NULL REFERENCES logical_trips(id),revision_ref INTEGER NOT NULL REFERENCES logical_revisions(id),
    material_version INTEGER NOT NULL CHECK(material_version>0),kind TEXT NOT NULL CHECK(kind IN ('context','initial','terminal','correction','uncertainty')),mode TEXT NOT NULL DEFAULT 'live' CHECK(mode IN ('live','backfill')),run_ref TEXT REFERENCES upload_scan_runs(run_id)) STRICT;
CREATE TRIGGER database_info_no_update BEFORE UPDATE ON database_info BEGIN SELECT RAISE(ABORT, 'database_info rows are immutable'); END;
CREATE TRIGGER database_info_no_delete BEFORE DELETE ON database_info BEGIN SELECT RAISE(ABORT, 'database_info rows are immutable'); END;
CREATE TRIGGER events_no_update BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT, 'events rows are immutable'); END;
CREATE TRIGGER events_no_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT, 'events rows are immutable'); END;
CREATE TRIGGER event_gaps_no_update BEFORE UPDATE ON event_gaps BEGIN SELECT RAISE(ABORT, 'event_gaps rows are immutable'); END;
CREATE TRIGGER event_gaps_no_delete BEFORE DELETE ON event_gaps BEGIN SELECT RAISE(ABORT, 'event_gaps rows are immutable'); END;
CREATE INDEX samples_session ON samples (plugin_session_ref, id);
CREATE INDEX samples_trip ON samples (trip_ref, id) WHERE trip_ref IS NOT NULL;
CREATE INDEX event_attributions_trip ON event_attributions (trip_ref);
CREATE INDEX completeness_intervals_trip ON completeness_intervals (trip_ref);
CREATE INDEX completeness_intervals_session ON completeness_intervals (plugin_session_ref);
CREATE VIEW logical_snapshot_memberships AS SELECT trip_ref,logical_ref,coalesce(joined_after_revision,0) AS from_revision,NULL AS through_revision FROM logical_memberships
    UNION ALL SELECT trip_ref,previous_logical_ref,0,joined_after_revision FROM logical_memberships WHERE previous_logical_ref IS NOT NULL;
CREATE INDEX logical_memberships_previous ON logical_memberships(previous_logical_ref,trip_ref);
CREATE INDEX logical_memberships_group ON logical_memberships(logical_ref, trip_ref);
CREATE INDEX logical_profile_slots ON logical_trips(game,profile_scope,retired,id);
CREATE INDEX logical_candidates ON logical_trips(game, profile_scope, fingerprint, retired);
CREATE INDEX logical_progress_cut ON logical_progress(logical_ref, truck_ref, start_odometer_m, odometer_m);
CREATE INDEX logical_revisions_group ON logical_revisions(logical_ref, id);
CREATE INDEX upload_projection_retained_root ON upload_projection_pins(root_ref);
CREATE TRIGGER upload_projection_trailer_insert AFTER INSERT ON trip_trailers BEGIN
    INSERT INTO upload_projection_evidence_versions(root_ref,generation)
  SELECT root,1 FROM (SELECT logical_ref AS root FROM logical_memberships WHERE trip_ref=NEW.trip_ref
  UNION SELECT previous_logical_ref FROM logical_memberships WHERE trip_ref=NEW.trip_ref) WHERE root IS NOT NULL
  ON CONFLICT(root_ref) DO UPDATE SET generation=generation+1; END;
CREATE TRIGGER upload_projection_trailer_delete AFTER DELETE ON trip_trailers BEGIN
    INSERT INTO upload_projection_evidence_versions(root_ref,generation)
  SELECT root,1 FROM (SELECT logical_ref AS root FROM logical_memberships WHERE trip_ref=OLD.trip_ref
  UNION SELECT previous_logical_ref FROM logical_memberships WHERE trip_ref=OLD.trip_ref) WHERE root IS NOT NULL
  ON CONFLICT(root_ref) DO UPDATE SET generation=generation+1; END;
CREATE TRIGGER upload_projection_trailer_update AFTER UPDATE ON trip_trailers BEGIN
    INSERT INTO upload_projection_evidence_versions(root_ref,generation)
  SELECT root,1 FROM (SELECT logical_ref AS root FROM logical_memberships WHERE trip_ref=OLD.trip_ref
  UNION SELECT previous_logical_ref FROM logical_memberships WHERE trip_ref=OLD.trip_ref UNION SELECT logical_ref AS root FROM logical_memberships WHERE trip_ref=NEW.trip_ref
  UNION SELECT previous_logical_ref FROM logical_memberships WHERE trip_ref=NEW.trip_ref) WHERE root IS NOT NULL
  ON CONFLICT(root_ref) DO UPDATE SET generation=generation+1; END;
CREATE TRIGGER upload_projection_interval_insert AFTER INSERT ON completeness_intervals BEGIN
    INSERT INTO upload_projection_evidence_versions(root_ref,generation)
  SELECT root,1 FROM (SELECT logical_ref AS root FROM logical_memberships WHERE trip_ref=NEW.trip_ref
  UNION SELECT previous_logical_ref FROM logical_memberships WHERE trip_ref=NEW.trip_ref) WHERE root IS NOT NULL
  ON CONFLICT(root_ref) DO UPDATE SET generation=generation+1; END;
